bool inWarehouse(int** grid, int gridSize, int* gridColSize, int target) {
    for (int r = 0; r < gridSize; r++) {
        int lo = 0, hi = gridColSize[r] - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (grid[r][mid] == target) return true;
            if (grid[r][mid] < target) lo = mid + 1; else hi = mid - 1;
        }
    }
    return false;
}

