class Solution {
    public boolean inWarehouse(int[][] grid, int target) {
        int r = 0, c = grid[0].length - 1;
        while (r < grid.length && c >= 0) {
            int v = grid[r][c];
            if (v == target) return true;
            if (v > target) c--;
            else r++;
        }
        return false;
    }
}

